using UnityEngine;using UnityEngine.SceneManagement;using System.Collections;using System.IO;using System.Linq;using System.Reflection;using Abyss.Story;
namespace IntegratedCampaign {
public sealed class CampaignVerification:MonoBehaviour {
 int errors;void Awake(){Application.logMessageReceived+=Log;}void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception)errors++;}void OnDestroy(){Application.logMessageReceived-=Log;}
 string log="";void Note(string s){log+=s+"\n";File.WriteAllText("Tools/CampaignIntegration/verification.txt",log);}void Check(bool ok,string s){Note((ok?"PASS ":"FAIL ")+s);if(!ok)throw new System.Exception(s);}
 IEnumerator Start(){DontDestroyOnLoad(gameObject);Application.runInBackground=true;var flow=CampaignFlow.Instance;Check(flow!=null,"one flow "+FindObjectsByType<CampaignFlow>(FindObjectsSortMode.None).Length);flow.NewGame();yield return Wait();Check(SceneManager.GetActiveScene().name==CampaignFlow.UnderwaterScene,"New game starts underwater");Check(flow.Phase==CampaignPhase.UnderwaterDiscovery&&flow.CalendarDay==1&&flow.Upgrades.Count==0,"clean progress day 1");
 var story=FindFirstObjectByType<UnderwaterDayStory>();story.secondChapter.firstChapterDepartureRequested.Invoke();yield return Wait();Check(flow.Phase==CampaignPhase.IntroVoyage,"first departure enters peaceful voyage");yield return ShipCheck(false);
 yield return Wait();Check(flow.CalendarDay==2&&flow.BattleWave==0,"day 2 independent of battle wave");story=FindFirstObjectByType<UnderwaterDayStory>();Check(story.secondChapter.Started,"second chapter restored");story.secondChapter.secondChapterCompleted.Invoke();yield return Wait();Check(flow.Phase==CampaignPhase.SmallFishBattle,"announcement leads to small fish battle");yield return ShipCheck(true);
 yield return Wait();story=FindFirstObjectByType<UnderwaterDayStory>();Check(story.thirdChapter.Started,"third chapter restored");story.thirdChapter.chapterCompleted.Invoke();yield return Wait();Check(flow.BattleWave==2,"shark battle");yield return ShipCheck(true);
 yield return Wait();Check(flow.BattleWave==3&&flow.Pollution==3,"whale battle pollution");yield return ShipCheck(true);var d=FindFirstObjectByType<ShipCampaignDirector>();yield return null;for(float deadline=Time.realtimeSinceStartup+12;Time.realtimeSinceStartup<deadline&&!GameObject.Find("Ending choices");){if(d.Dialogue.Active)d.Dialogue.Advance();yield return null;}Check(GameObject.Find("Ending choices")!=null,"complete final dialogue reaches ending choices");Check(GameObject.Find("White ceasefire flag")!=null,"final flag visible");ScreenCapture.CaptureScreenshot("Tools/CampaignIntegration/final.png");yield return null;flow.ReturnMenu();yield return Wait();Check(SceneManager.GetActiveScene().name==CampaignFlow.MenuScene,"return menu");flow.NewGame();yield return Wait();Check(flow.Upgrades.Count==0&&flow.CalendarDay==1&&flow.Pollution==0,"restart resets progress");Check(errors==0,"no runtime errors during adapter flow");Note("AUTOMATED ADAPTER FLOW COMPLETE. Story events invoked; not a full human gameplay test.");}
 IEnumerator Wait(){yield return new WaitForSecondsRealtime(2);while(CampaignFlow.Instance.Transitioning)yield return null;yield return new WaitForSecondsRealtime(.5f);}
 IEnumerator ShipCheck(bool battle){var d=FindFirstObjectByType<ShipCampaignDirector>();Check(d!=null&&d.Dialogue!=null,"ship director bound");Check(FindObjectsByType<CampaignFlow>(FindObjectsSortMode.None).Length==1&&FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Length==1&&FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsSortMode.None).Length==1,"single flow listener input");Check(d.smallFish.Length>0&&d.sharks.Length>0&&d.whales.Length>0,"all native enemy pools bound");Check(!GameObject.Find("White ceasefire flag"),"flag initially hidden");Check(FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length==0,"no enemies at dock");yield return new WaitForSecondsRealtime(.1f);Check(d.Dialogue.CurrentText.Length>0,"opening dialogue present");d.Dialogue.Clear();yield return null;Check(Time.timeScale==1,"controls unpause");var flow=CampaignFlow.Instance;var phase=flow.Phase;flow.RetryShip();yield return Wait();Check(flow.Phase==phase,"retry retains expedition");d=FindFirstObjectByType<ShipCampaignDirector>();d.Dialogue.Clear();yield return null;if(battle){d.Spawner.spawnInterval=.05f;d.gameObject.GetComponent<Rigidbody2D>().position=new Vector2(-18,0);yield return new WaitForSecondsRealtime(.2f);d.Dialogue.Clear();for(int i=0;i<600&&!d.WaveCleared;i++){foreach(var e in FindObjectsByType<Enemy>(FindObjectsSortMode.None))e.TakeDamage(10000,Vector2.zero);var ui=FindFirstObjectByType<ShipUIManager>();if(ui.levelUpOverlay&&ui.levelUpOverlay.activeSelf)ui.OnCardClicked(0);yield return null;}Check(d.Spawner.CampaignSpawned==d.Spawner.CampaignBudget&&d.WaveCleared,"finite native enemy wave completes without endless spawning");}
 if(flow.Phase!=CampaignPhase.WhaleBattle){var expected=flow.Phase==CampaignPhase.IntroVoyage?CampaignPhase.Announcement:flow.Phase==CampaignPhase.SmallFishBattle?CampaignPhase.SharkJourney:CampaignPhase.WhaleBattle;d.GetType().GetProperty("Tank").GetSetMethod(true).Invoke(d,new object[]{1f});d.GetComponent<Rigidbody2D>().position=d.dockPoint;yield return null;d.Dialogue.Clear();d.StartCoroutine("Deliver");for(int i=0;i<600&&!flow.Transitioning;i++){if(d.Dialogue.Active)d.Dialogue.Advance();var ui=FindFirstObjectByType<ShipUIManager>();if(ui.levelUpOverlay&&ui.levelUpOverlay.activeSelf)ui.OnCardClicked(0);yield return null;}yield return Wait();Check(flow.Phase==expected,"real expedition delivery advances to "+expected);}
 }

}
}
